import { createAgentServiceSandboxTools } from "../../sandbox/index.js";
import { importFirstPartyExtensionModule } from "../../extensions/first-party-import.js";
import { canonicalPlatformHostTools } from "../platform-host-tools.js";
import { markTrustedHostToolSet } from "../../tool/host-tool-provenance.js";
import { markTrustedPlatformSource } from "../../tool/platform-source-provenance.js";
import { privateJsonParse } from "../../security/private-json.js";
import { VERYFRONT_API_MCP_SOURCE_ID } from "../runtime/mcp-server-tool-sources.js";
import { createPrivateAsyncLocalStorage } from "../../security/private-async-context.js";
import { createPrivateWeakStore } from "../../security/private-weak-store.js";
import { createPrivateMap } from "../../security/private-map.js";
import { forEachPrivateArray, mapPrivateArray, pushPrivateArray, somePrivateArray, } from "../../security/private-array.js";
import { privateTextSplit } from "../../security/private-text.js";
import { configureHostedPlatformDependencySource, hostedPlatformDependencyCredential, registerHostedPlatformDependencyRequest, revokeHostedPlatformDependencies, runWithHostedPlatformDependencies, } from "../hosted/platform-dependency-credential.js";
import { bindHostedToolCallAdmissionWriter, } from "../hosted/child-run-event-writer-token.js";
import { hostedTerminalToolSourceFactory } from "../hosted/terminal-credential.js";
import { createConnectedLocalWriterVerifier } from "../service/auth.js";
import { createLivePlatformMcpSource } from "../platform-mcp-tool-source.js";
import { createRemoteMCPToolSourceFactoryWithTransport, } from "../../tool/index.js";
import { runWithExactRuntimeRemoteToolSources } from "../runtime/remote-tool-source-context.js";
import { runWithRecoveryToolExecutionPolicy } from "../../runtime/execution-ownership-guard.js";
import { getCurrentToolCallOccurrenceIdentity, runWithToolCallOccurrences, } from "../../runtime/tool-call-occurrence.js";
import { bindToolCallAdmissionOwner, runWithToolCallAdmissionReceipt, } from "../../runtime/tool-call-admission-dispatch.js";
import { runWithVerifiedSkillScriptExecutionCredential } from "../../skill/execution-credential.js";
const execution = createPrivateAsyncLocalStorage();
const apply = Reflect.apply;
const nativeBuffer = Buffer;
const nativePromise = Promise;
const bufferFrom = Buffer.from;
const bufferToString = Buffer.prototype.toString;
const isArray = Array.isArray;
const entries = Object.entries;
const replace = String.prototype.replace;
const allSettled = Promise.allSettled;
/** CLI-owned transport and signed grants; no project setting can install this boundary. */
export function createConnectedLocalPlatformTools(apiUrl, transport, dependencies = {}) {
    const verify = createConnectedLocalWriterVerifier(apiUrl);
    const endpoint = `${apply(replace, apiUrl, [/\/$/, ""])}/mcp`;
    const createSource = createRemoteMCPToolSourceFactoryWithTransport({
        trustedEndpoints: [endpoint],
        requestFetch: transport,
    });
    const sources = createPrivateWeakStore();
    const credentials = createPrivateWeakStore();
    const freezeCredentials = createPrivateWeakStore();
    const childOwners = createPrivateWeakStore();
    const credentialLifetimes = createPrivateWeakStore();
    const cleanups = createPrivateWeakStore();
    const freezeCredentialTree = (owner) => {
        freezeCredentials.get(owner)?.();
        forEachPrivateArray(childOwners.get(owner) ?? [], freezeCredentialTree);
    };
    const revoke = async (owner) => {
        // Snapshot the newest exact-owner credential before revoking execution
        // authority so retained cleanup never falls back to its admission token.
        freezeCredentialTree(owner);
        revokeHostedPlatformDependencies(owner);
        const pending = cleanups.get(owner) ?? [];
        cleanups.set(owner, []);
        const results = await apply(allSettled, nativePromise, [
            mapPrivateArray(pending, async (close) => await close()),
        ]);
        const retry = [];
        let failure;
        forEachPrivateArray(results, (result, index) => {
            if (result.status !== "rejected")
                return;
            const close = pending[index];
            if (close)
                pushPrivateArray(retry, close);
            failure ??= result.reason;
        });
        if (retry.length > 0) {
            const current = cleanups.get(owner) ?? [];
            forEachPrivateArray(retry, (close) => pushPrivateArray(current, close));
            cleanups.set(owner, current);
            throw failure;
        }
        const credentialLifetime = credentialLifetimes.get(owner);
        if (credentialLifetime)
            credentialLifetime.active = false;
    };
    return {
        verify,
        revoke,
        async register(owner, scope, eventToken, authToken, currentAuthority) {
            const verification = await verify({ ...scope, token: eventToken });
            if (!verification.verified)
                throw new Error("Connected local writer verification failed");
            registerHostedPlatformDependencyRequest(owner, verification, scope, verify, authToken);
            const cleanup = [];
            cleanups.set(owner, cleanup);
            try {
                await configureHostedPlatformDependencySource(owner, async (childScope, token, childOwner, parentOwner) => {
                    let ownerCleanup = cleanups.get(childOwner);
                    if (!ownerCleanup) {
                        ownerCleanup = [];
                        cleanups.set(childOwner, ownerCleanup);
                        if (childOwner !== owner) {
                            const parent = parentOwner ?? owner;
                            const descendants = childOwners.get(parent) ?? [];
                            pushPrivateArray(descendants, childOwner);
                            childOwners.set(parent, descendants);
                            const parentCleanup = cleanups.get(parent);
                            if (!parentCleanup) {
                                throw new Error("Connected platform sandbox parent is unavailable");
                            }
                            pushPrivateArray(parentCleanup, () => revoke(childOwner));
                        }
                    }
                    try {
                        credentialLifetimes.set(childOwner, { active: true });
                        let lastCredential = token;
                        let credentialFrozen = false;
                        const credential = () => {
                            if (credentialFrozen)
                                return lastCredential;
                            const current = childScope.runId === scope.runId
                                ? currentAuthority?.().auth_token
                                : hostedPlatformDependencyCredential(childOwner);
                            if (current)
                                lastCredential = current;
                            return lastCredential;
                        };
                        freezeCredentials.set(childOwner, () => {
                            if (credentialFrozen)
                                return;
                            credential();
                            credentialFrozen = true;
                        });
                        credentials.set(childOwner, credential);
                        const factory = hostedTerminalToolSourceFactory(childOwner, endpoint, createSource);
                        let source = createLivePlatformMcpSource(factory({
                            id: VERYFRONT_API_MCP_SOURCE_ID,
                            endpoint,
                            headers: () => {
                                const current = childScope.runId === scope.runId
                                    ? currentAuthority?.()
                                    : undefined;
                                return {
                                    Authorization: `Bearer ${credential()}`,
                                    ...(childScope.runId === scope.runId
                                        ? { "X-Veryfront-Run-Event-Token": current?.run_event_token ?? eventToken }
                                        : {}),
                                };
                            },
                        }, { id: VERYFRONT_API_MCP_SOURCE_ID, kind: "veryfront-api" }));
                        // The API issues this scope only for this child's sealed sandbox selection.
                        let allowSandbox = false;
                        try {
                            const claims = privateJsonParse(apply(bufferToString, apply(bufferFrom, nativeBuffer, [
                                privateTextSplit(token, ".")[1],
                                "base64url",
                            ]), []));
                            allowSandbox = isArray(claims.scope) &&
                                somePrivateArray(claims.scope, (scope) => scope === "sandboxes:write");
                        }
                        catch { /* A session credential without sandbox scope exposes no native tools. */ }
                        if (allowSandbox) {
                            const { createBashSandboxShellToolsProvider } = await importFirstPartyExtensionModule("ext-sandbox-shell-tools", "@veryfront/ext-sandbox-shell-tools");
                            const sandbox = await (dependencies.createSandboxTools ?? createAgentServiceSandboxTools)({
                                apiUrl,
                                authToken: token,
                                getAuthToken: credential,
                                getProjectId: () => childScope.projectId,
                                createBashTool: createBashSandboxShellToolsProvider,
                            });
                            if (cleanups.get(childOwner) !== ownerCleanup) {
                                await sandbox.closeSandbox();
                                throw new Error("Connected platform sandbox owner is no longer active");
                            }
                            pushPrivateArray(ownerCleanup, sandbox.closeSandbox);
                            const native = canonicalPlatformHostTools(markTrustedHostToolSet(sandbox.tools));
                            const mcp = source;
                            source = markTrustedPlatformSource({
                                id: mcp.id,
                                listTools: async (context) => [
                                    ...await mcp.listTools(context),
                                    ...mapPrivateArray(entries(native), ([name, tool]) => ({
                                        name,
                                        description: tool.description ?? name,
                                        parameters: (tool.inputSchemaJson ?? tool.parameters ??
                                            { type: "object", properties: {} }),
                                    })),
                                ],
                                executeTool: async (name, input, context) => {
                                    const tool = native[name];
                                    if (!tool)
                                        return mcp.executeTool(name, input, context);
                                    if (!tool.execute)
                                        throw new Error("Sandbox tool cannot execute");
                                    return await tool.execute(input, context);
                                },
                            });
                        }
                        sources.set(childOwner, source);
                        return source;
                    }
                    catch (error) {
                        await revoke(childOwner);
                        throw error;
                    }
                });
            }
            catch (error) {
                await revoke(owner);
                throw error;
            }
        },
        run(input, operation) {
            const identity = {};
            const assertCredentialActive = () => {
                if (credentialLifetimes.get(input.owner)?.active !== true) {
                    throw new Error("Connected run credential is no longer active");
                }
            };
            const assertToolActive = () => {
                input.signal.throwIfAborted();
                assertCredentialActive();
            };
            const calls = createPrivateMap();
            const admit = (call) => {
                const tool = calls.get(call.occurrenceId);
                if (!tool)
                    throw new Error("Missing connected tool dispatch");
                return input.admit(call, tool.name, tool.args);
            };
            bindHostedToolCallAdmissionWriter(admit, {
                capability: input.writer,
                expectedRunId: input.scope.runId,
                projectId: input.scope.projectId,
            });
            bindToolCallAdmissionOwner(admit, { ...input.scope, canonicalRunId: input.canonicalRunId });
            const registeredSource = sources.get(input.owner);
            // Worker event scopes may use a public ID. Run queries use the admitted
            // canonical UUID, scoped to this execution rather than retained globally.
            const source = registeredSource
                ? createLivePlatformMcpSource(registeredSource, {
                    runId: input.canonicalRunId,
                    runIdBindsToolAuthorization: true,
                })
                : undefined;
            const credential = credentials.get(input.owner);
            if (!credential)
                throw new Error("Connected run credential is unavailable");
            const projectContext = dependencies.projectContext;
            // Legacy writers have no delegated dependency runner, but still retain their
            // directly authenticated first-party platform source.
            return runWithHostedPlatformDependencies(input.owner, () => runWithVerifiedSkillScriptExecutionCredential({
                assertActive: assertCredentialActive,
                read: () => ({
                    apiUrl,
                    authToken: credential(),
                    projectId: input.scope.projectId,
                    ...(projectContext ? { projectSlug: projectContext.projectSlug } : {}),
                    ...(projectContext ? { branch: projectContext.branch } : {}),
                    runId: input.scope.runId,
                    agentId: input.scope.agentId,
                }),
            }, () => runWithExactRuntimeRemoteToolSources(source ? [source] : [], () => execution.run(identity, () => runWithToolCallOccurrences(() => runWithRecoveryToolExecutionPolicy(async (tool, execute) => {
                // A nested child owns its own receipt, never its parent's.
                if (execution.getStore() !== identity) {
                    return execute();
                }
                assertToolActive();
                const call = getCurrentToolCallOccurrenceIdentity();
                if (!call) {
                    throw new Error("Connected tool has no private occurrence");
                }
                calls.set(call.occurrenceId, { name: tool.toolName, args: tool.input });
                const receipt = await admit(call, input.signal);
                calls.delete(call.occurrenceId);
                return runWithToolCallAdmissionReceipt(receipt, assertToolActive, execute, admit);
            }, operation))))));
        },
    };
}
